//! OpenVSwitch D-Bus Daemon
//!
//! Provides D-Bus interfaces for OVSDB and OpenFlow operations via native
//! rovs primitives. This daemon replaces OvsdbClient CLI wrappers with a
//! schema-driven D-Bus service.
//!
//! D-Bus object path: /opdbus/v1/plugins/ovsdb
//!
//! Interfaces:
//! - org.opdbus.v1.Ovsdb.JsonRpc (transact method for OVSDB operations)
//! - org.opdbus.v1.Ovsdb.OpenFlow (passive controller absorption)
//!
//! ## Architecture
//!
//! Per AGENTS.md D-Bus-first rules:
//! - All OVS state changes go through D-Bus methods
//! - rovs-jsonrpc::Connection is used for OVSDB JSON-RPC wire protocol
//! - rovs-openflow::VConn handles OpenFlow controller connections
//! - No subprocess spawning - pure Rust native implementation
//!
//! ## Modes
//! - D-Bus mode (default): Runs as D-Bus service only
//! - gRPC mode: Adds gRPC server that proxies to D-Bus

use anyhow::{Context, Result};
use rovs_ovsdb::{Client, ClientConfig};
use std::path::Path;
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{info, warn};
use zbus::connection::Connection;

mod dbus;
mod grpc;
mod openflow_proxy;
mod ovsdb_proxy;

use dbus::OvsdbDBusService;

/// CLI arguments
#[derive(Debug, Clone)]
struct Args {
    /// gRPC listen address (enables gRPC mode)
    grpc_addr: Option<String>,
    /// OVS socket path override
    ovs_socket: Option<String>,
}

impl Args {
    fn parse() -> Self {
        let args: Vec<String> = std::env::args().collect();
        let mut grpc_addr = None;
        let mut ovs_socket = None;

        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "--grpc" => {
                    if i + 1 < args.len() {
                        grpc_addr = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                "--ovs-socket" => {
                    if i + 1 < args.len() {
                        ovs_socket = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                _ => i += 1,
            }
        }

        Self {
            grpc_addr,
            ovs_socket,
        }
    }
}

/// Default OVS socket path
const DEFAULT_OVS_SOCKET: &str = "/var/run/openvswitch/db.sock";

/// Alternative socket paths to try
const OVS_SOCKET_PATHS: &[&str] = &["/run/openvswitch/db.sock", "/var/run/openvswitch/db.sock"];

/// Find the OVS socket path
fn find_ovs_socket() -> String {
    OVS_SOCKET_PATHS
        .iter()
        .find(|p| Path::new(p).exists())
        .unwrap_or(&DEFAULT_OVS_SOCKET)
        .to_string()
}

/// Daemon state holding OVS connections
#[derive(Clone)]
pub struct DaemonState {
    /// OVSDB client for database operations
    pub ovsdb: Arc<Mutex<Option<Client>>>,
    /// Socket path for OVSDB connection
    pub socket_path: String,
}

impl DaemonState {
    fn new(socket_path: String) -> Self {
        Self {
            ovsdb: Arc::new(Mutex::new(None)),
            socket_path,
        }
    }

    /// Get or create OVSDB client
    async fn get_ovsdb(&self) -> Result<tokio::sync::MutexGuard<'_, Option<Client>>> {
        let mut guard = self.ovsdb.lock().await;

        if guard.is_none() {
            let config = ClientConfig::default().database("Open_vSwitch");

            let addr = format!("unix:{}", self.socket_path);
            let client = Client::connect_with_config(&addr, config)
                .await
                .context("Failed to connect to OVSDB")?;

            info!("Connected to OVSDB at {}", self.socket_path);
            *guard = Some(client);
        }

        Ok(guard)
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    // Initialize logging
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    info!("Starting op-openvswitch-daemon");

    // Parse CLI arguments
    let args = Args::parse();

    // Find OVS socket
    let socket_path = args.ovs_socket.unwrap_or_else(find_ovs_socket);
    info!("Using OVS socket: {}", socket_path);

    // Create daemon state
    let state = DaemonState::new(socket_path);

    // Test connection early
    if let Err(e) = state.get_ovsdb().await {
        warn!(
            "Could not connect to OVSDB: {}. Daemon will retry on first request.",
            e
        );
    }

    // Create D-Bus service
    let service = OvsdbDBusService::new(state);

    // Build D-Bus connection
    let conn = Connection::system()
        .await
        .context("Failed to connect to system D-Bus")?;

    info!("Connected to system D-Bus");

    // Serve the OvsdbDBusService on the connection
    conn.object_server()
        .at("/opdbus/v1/plugins/ovsdb", service)
        .await
        .context("Failed to register D-Bus object")?;

    // Request the bus name
    conn.request_name("opdbus.v1.plugins.ovsdb")
        .await
        .context("Failed to request bus name")?;

    info!("D-Bus service registered at /opdbus/v1/plugins/ovsdb");

    // Optionally start gRPC server
    if let Some(grpc_addr) = args.grpc_addr {
        let addr: std::net::SocketAddr = grpc_addr.parse().context("Invalid gRPC address")?;

        info!("Starting gRPC server on {}", addr);

        // Spawn gRPC server in background task
        tokio::spawn(async move {
            if let Err(e) = grpc::run_grpc_server(addr).await {
                warn!("gRPC server error: {}", e);
            }
        });
    }

    info!("Daemon ready - press Ctrl+C to stop");

    // Keep the connection alive
    loop {
        tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    }
}

//! D-Bus Service Implementation for OpenVSwitch
//!
//! Implements the org.opdbus.v1.Ovsdb.JsonRpc and org.opdbus.v1.Ovsdb.OpenFlow
//! interfaces as defined in the plugin schema.

use crate::DaemonState;
use simd_json::prelude::{ValueAsScalar, ValueObjectAccess};
use tracing::{debug, warn};
use zbus::interface;

/// D-Bus service for OVSDB operations
pub struct OvsdbDBusService {
    state: DaemonState,
}

impl OvsdbDBusService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

#[interface(name = "opdbus.v1.Ovsdb.JsonRpc")]
impl OvsdbDBusService {
    /// Execute an OVSDB transaction via JSON-RPC
    ///
    /// Takes a JSON-encoded transaction request and returns the JSON-encoded
    /// response from OVSDB. This is the primary method for OVSDB operations.
    ///
    /// # Arguments
    /// * `request_json` - JSON string containing the OVSDB operation
    ///
    /// # Returns
    /// JSON string with the operation result or error
    async fn transact(&self, request_json: String) -> String {
        debug!("Received transact request: {}", request_json);

        // Parse the request JSON
        let mut bytes = request_json.into_bytes();
        let request: simd_json::OwnedValue = match simd_json::from_slice(&mut bytes) {
            Ok(v) => v,
            Err(e) => {
                warn!("Failed to parse request JSON: {}", e);
                return format!("{{\"error\":\"Invalid JSON: {}\"}}", e);
            }
        };

        // Get OVSDB client
        let mut client_guard = match self.state.get_ovsdb().await {
            Ok(g) => g,
            Err(e) => {
                warn!("OVSDB connection failed: {}", e);
                return format!("{{\"error\":\"OVSDB connection failed: {}\"}}", e);
            }
        };

        let client = match client_guard.as_mut() {
            Some(c) => c,
            None => {
                return r#"{"error":"OVSDB client not available"}"#.to_string();
            }
        };

        // Extract operation from request
        let operation = request
            .get("operation")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown");

        let result = match operation {
            "create_bridge" => {
                let bridge_name = request.get("name").and_then(|v| v.as_str()).unwrap_or("");

                let mut txn = rovs_ovsdb::Transaction::new("Open_vSwitch");
                txn.create_bridge(bridge_name);

                match client.commit(&mut txn).await {
                    Ok(true) => format!(
                        "{{\"result\":\"Bridge '{}' created successfully\"}}",
                        bridge_name
                    ),
                    Ok(false) => {
                        "{\"error\":\"Bridge creation transaction returned false\"}".to_string()
                    }
                    Err(e) => format!("{{\"error\":\"Bridge creation failed: {}\"}}", e),
                }
            }
            "delete_bridge" => {
                let bridge_name = request.get("name").and_then(|v| v.as_str()).unwrap_or("");

                // Look up bridge UUID from IDL
                let idl = client.idl();
                let bridge_row = idl
                    .rows("Bridge")
                    .find(|r| r.get_string("name") == Some(bridge_name));

                match bridge_row {
                    Some(row) => {
                        let bridge_uuid = row.uuid;

                        // Collect port UUIDs - note: row.get returns &serde_json::Value
                        let mut port_uuids: Vec<uuid::Uuid> = Vec::new();
                        if let Some(ports_val) = row.get("ports") {
                            // Use helper to extract UUIDs from JSON Value
                            collect_uuid_set_from_value(ports_val, &mut port_uuids);
                        }

                        // Collect interface UUIDs
                        let mut iface_uuids: Vec<uuid::Uuid> = Vec::new();
                        for port_uuid in &port_uuids {
                            if let Some(port_row) = idl.row("Port", port_uuid) {
                                if let Some(ifaces_val) = port_row.get("interfaces") {
                                    collect_uuid_set_from_value(ifaces_val, &mut iface_uuids);
                                }
                            }
                        }

                        // Build and execute delete transaction
                        let mut txn = rovs_ovsdb::Transaction::new("Open_vSwitch");
                        txn.delete_bridge_uuid(bridge_uuid, &port_uuids, &iface_uuids);

                        match client.commit(&mut txn).await {
                            Ok(true) => format!(
                                "{{\"result\":\"Bridge '{}' deleted successfully\"}}",
                                bridge_name
                            ),
                            Ok(false) => {
                                "{\"error\":\"Bridge deletion transaction returned false\"}"
                                    .to_string()
                            }
                            Err(e) => format!("{{\"error\":\"Bridge deletion failed: {}\"}}", e),
                        }
                    }
                    None => format!("{{\"error\":\"Bridge '{}' not found\"}}", bridge_name),
                }
            }
            "add_port" => {
                let bridge_name = request.get("bridge").and_then(|v| v.as_str()).unwrap_or("");
                let port_name = request.get("port").and_then(|v| v.as_str()).unwrap_or("");

                let mut txn = rovs_ovsdb::Transaction::new("Open_vSwitch");
                txn.add_port(bridge_name, port_name, "system");

                match client.commit(&mut txn).await {
                    Ok(true) => format!(
                        "{{\"result\":\"Port '{}' added to bridge '{}'\"}}",
                        port_name, bridge_name
                    ),
                    Ok(false) => "{\"error\":\"Add port transaction returned false\"}".to_string(),
                    Err(e) => format!("{{\"error\":\"Add port failed: {}\"}}", e),
                }
            }
            "list_bridges" => {
                let idl = client.idl();
                let bridges: Vec<String> = idl
                    .rows("Bridge")
                    .filter_map(|r| r.get_string("name"))
                    .map(String::from)
                    .collect();

                let bridge_list = bridges
                    .iter()
                    .map(|b| format!("\"{}\"", b))
                    .collect::<Vec<_>>()
                    .join(",");

                format!(
                    "{{\"bridges\":[{}],\"count\":{}}}",
                    bridge_list,
                    bridges.len()
                )
            }
            "list_ports" => {
                let bridge_name = request.get("bridge").and_then(|v| v.as_str()).unwrap_or("");

                let idl = client.idl();

                match idl
                    .rows("Bridge")
                    .find(|r| r.get_string("name") == Some(bridge_name))
                {
                    Some(row) => {
                        let mut port_uuids = Vec::new();
                        if let Some(ports_val) = row.get("ports") {
                            collect_uuid_set_from_value(ports_val, &mut port_uuids);
                        }

                        let port_names: Vec<String> = port_uuids
                            .iter()
                            .filter_map(|uuid| {
                                idl.row("Port", uuid)
                                    .and_then(|p| p.get_string("name"))
                                    .map(String::from)
                            })
                            .collect();

                        let port_list = port_names
                            .iter()
                            .map(|p| format!("\"{}\"", p))
                            .collect::<Vec<_>>()
                            .join(",");

                        format!(
                            "{{\"bridge\":\"{}\",\"ports\":[{}],\"count\":{}}}",
                            bridge_name,
                            port_list,
                            port_names.len()
                        )
                    }
                    None => format!("{{\"error\":\"Bridge '{}' not found\"}}", bridge_name),
                }
            }
            "list_dbs" => match client.list_dbs().await {
                Ok(dbs) => {
                    let db_list = dbs
                        .iter()
                        .map(|d| format!("\"{}\"", d))
                        .collect::<Vec<_>>()
                        .join(",");
                    format!("{{\"databases\":[{}]}}", db_list)
                }
                Err(e) => format!("{{\"error\":\"List databases failed: {}\"}}", e),
            },
            _ => {
                format!("{{\"error\":\"Unknown operation: {}\"}}", operation)
            }
        };

        result
    }

    /// Get the daemon status
    async fn status(&self) -> String {
        let connected = self.state.ovsdb.lock().await.is_some();

        format!(
            "{{\"connected\":{},\"socket_path\":\"{}\",\"version\":\"{}\"}}",
            connected,
            self.state.socket_path,
            env!("CARGO_PKG_VERSION")
        )
    }
}

/// Extract UUIDs from an OVSDB set value (JSON Value version)
pub(crate) fn collect_uuid_set_from_value(value: &serde_json::Value, uuids: &mut Vec<uuid::Uuid>) {
    // OVSDB represents sets as ["set", [uuid1, uuid2, ...]]
    if let Some(arr) = value.as_array() {
        if arr.len() == 2 && arr[0].as_str() == Some("set") {
            if let Some(set_arr) = arr[1].as_array() {
                for item in set_arr {
                    if let Some(uuid_arr) = item.as_array() {
                        if uuid_arr.len() == 2 && uuid_arr[0].as_str() == Some("uuid") {
                            if let Some(uuid_str) = uuid_arr[1].as_str() {
                                if let Ok(uuid) = uuid::Uuid::parse_str(uuid_str) {
                                    uuids.push(uuid);
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

//! OVSDB Proxy - Bridges rovs-jsonrpc to D-Bus
//!
//! Provides structured operations for common OVSDB tasks like
//! bridge management, port operations, and database queries.
//!
//! This module encapsulates the rovs_ovsdb::Client operations
//! behind a clean Rust API that the D-Bus interface uses.

#![allow(dead_code)]

use anyhow::{Context, Result};
use rovs_ovsdb::{Client, Transaction};
use serde_json::json;
use std::collections::HashMap;
use tracing::info;

/// Bridge configuration structure
#[derive(Debug, Clone, Default)]
