pub enum MultipartType {
    /// Switch description
    Desc = 0,
    /// Individual flow statistics
    Flow = 1,
    /// Aggregate flow statistics
    Aggregate = 2,
    /// Flow table statistics
    Table = 3,
    /// Port statistics
    PortStats = 4,
    /// Queue statistics
    Queue = 5,
    /// Group statistics
    Group = 6,
    /// Group description
    GroupDesc = 7,
    /// Group features
    GroupFeatures = 8,
    /// Meter statistics
    Meter = 9,
    /// Meter configuration
    MeterConfig = 10,
    /// Meter features
    MeterFeatures = 11,
    /// Table features
    TableFeatures = 12,
    /// Port description
    PortDesc = 13,
    /// Experimenter extension
    Experimenter = 0xffff,
}

impl TryFrom<u16> for MultipartType {
    type Error = crate::Error;

    fn try_from(v: u16) -> Result<Self, Self::Error> {
        match v {
            0 => Ok(Self::Desc),
            1 => Ok(Self::Flow),
            2 => Ok(Self::Aggregate),
            3 => Ok(Self::Table),
            4 => Ok(Self::PortStats),
            5 => Ok(Self::Queue),
            6 => Ok(Self::Group),
            7 => Ok(Self::GroupDesc),
            8 => Ok(Self::GroupFeatures),
            9 => Ok(Self::Meter),
            10 => Ok(Self::MeterConfig),
            11 => Ok(Self::MeterFeatures),
            12 => Ok(Self::TableFeatures),
            13 => Ok(Self::PortDesc),
            0xffff => Ok(Self::Experimenter),
            _ => Err(crate::Error::Parse(format!(
