    type Error = Error;

    fn try_from(v: u8) -> Result<Self> {
        match v {
            0 => Ok(Self::NoMatch),
            1 => Ok(Self::Action),
            2 => Ok(Self::InvalidTtl),
            3 => Ok(Self::ActionSet),
            4 => Ok(Self::Group),
            5 => Ok(Self::PacketOut),
