        let bridge_uuid = match bridge_rows {
            Some(rows) if !rows.is_empty() => {
                rows[0].get("_uuid")
                    .and_then(|u| u.as_array())
                    .and_then(|a| a.get(1))
                    .and_then(|v| v.as_str())
                    .map(String::from)
                    .ok_or_else(|| anyhow::anyhow!("bridge UUID not found"))?
