        info!("gRPC delete_bridge: {}", name);

        let client = self.state.get_ovsdb().await.map_err(|e| {
            Status::internal(format!("OVSDB not available: {}", e))
        })?;

        // Find bridge UUID
        let find_ops = vec![
            serde_json::json!({
